package com.example.studentintelligentsystem;

/**
 * Model class representing a student result record
 */
public class Result {
    private int resultId;
    private int studentId;
    private String studentName;
    private String subject;
    private String term;
    private int marks;
    private String comment;

    public Result() {}

    public Result(int resultId, int studentId, String studentName, String subject, String term, int marks, String comment) {
        this.resultId = resultId;
        this.studentId = studentId;
        this.studentName = studentName;
        this.subject = subject;
        this.term = term;
        this.marks = marks;
        this.comment = comment;
    }

    public int getResultId() {
        return resultId;
    }

    public void setResultId(int resultId) {
        this.resultId = resultId;
    }

    public int getStudentId() {
        return studentId;
    }

    public void setStudentId(int studentId) {
        this.studentId = studentId;
    }

    public String getStudentName() {
        return studentName;
    }

    public void setStudentName(String studentName) {
        this.studentName = studentName;
    }

    public String getSubject() {
        return subject;
    }

    public void setSubject(String subject) {
        this.subject = subject;
    }

    public String getTerm() {
        return term;
    }

    public void setTerm(String term) {
        this.term = term;
    }

    public int getMarks() {
        return marks;
    }

    public void setMarks(int marks) {
        this.marks = marks;
    }

    public String getComment() {
        return comment;
    }

    public void setComment(String comment) {
        this.comment = comment;
    }
}

package com.example.studentintelligentsystem;

import android.app.Application;
import android.util.Log;
import com.example.studentintelligentsystem.supabase.SupabaseClient;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

/**
 * Application class for Student Intelligent System
 * Initializes Supabase on app startup
 */
public class StudentIntelligentSystemApp extends Application {
    private static final String TAG = "StudentIntelligentApp";

    @Override
    public void onCreate() {
        super.onCreate();
        Log.i(TAG, "Application starting...");

        // Initialize Supabase
        initializeSupabase();
    }

    private void initializeSupabase() {
        try {
            Log.i(TAG, "Initializing Supabase connection...");

            // Check if Supabase is configured
            if (!SupabaseConfig.isConfigured()) {
                Log.e(TAG, "Supabase is NOT configured. Please check local.properties file.");
                Log.e(TAG, "Expected: SUPABASE_URL and SUPABASE_ANON_KEY");
                return;
            }

            Log.d(TAG, "Supabase URL: " + SupabaseConfig.SUPABASE_URL);
            Log.d(TAG, "Supabase API Key configured: " + (SupabaseConfig.SUPABASE_ANON_KEY != null && !SupabaseConfig.SUPABASE_ANON_KEY.isEmpty()));

            // Initialize Supabase client
            SupabaseClient.initialize(this);

            Log.i(TAG, "✓ Supabase initialized successfully!");
            Log.i(TAG, "✓ Supabase is ready for data synchronization");

            // Test connection in background
            testSupabaseConnection();

        } catch (Exception e) {
            Log.e(TAG, "✗ Failed to initialize Supabase: " + e.getMessage(), e);
        }
    }

    private void testSupabaseConnection() {
        new Thread(() -> {
            try {
                Log.d(TAG, "Testing Supabase connection...");
                boolean isConnected = SupabaseClient.getInstance().testConnection();

                if (isConnected) {
                    Log.i(TAG, "✓ Supabase connection test SUCCESSFUL");
                    Log.i(TAG, "✓ Data sync is enabled and operational");
                } else {
                    Log.w(TAG, "✗ Supabase connection test FAILED");
                    Log.w(TAG, "✗ Data sync may not work properly");
                }
            } catch (Exception e) {
                Log.e(TAG, "✗ Supabase connection test error: " + e.getMessage(), e);
            }
        }).start();
    }
}

package com.example.studentintelligentsystem;

import android.app.Application;
import android.content.SharedPreferences;
import android.util.Log;
import com.example.studentintelligentsystem.supabase.SupabaseClient;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;
import com.example.studentintelligentsystem.supabase.SupabaseSyncManager;

/**
 * Application class for Student Intelligent System
 * Initializes Supabase on app startup and syncs existing data
 */
public class StudentIntelligentSystemApp extends Application {
    private static final String TAG = "StudentIntelligentApp";
    private static final String PREFS_NAME = "SupabaseSyncPrefs";
    private static final String KEY_INITIAL_SYNC_DONE = "initial_sync_completed";

    @Override
    public void onCreate() {
        super.onCreate();
        Log.i(TAG, "Application starting...");

        // Initialize Supabase
        initializeSupabase();
    }

    private void initializeSupabase() {
        try {
            Log.i(TAG, "Initializing Supabase connection...");

            // Check if Supabase is configured
            if (!SupabaseConfig.isConfigured()) {
                Log.e(TAG, "Supabase is NOT configured. Please check local.properties file.");
                Log.e(TAG, "Expected: SUPABASE_URL and SUPABASE_ANON_KEY");
                return;
            }

            Log.d(TAG, "Supabase URL: " + SupabaseConfig.SUPABASE_URL);
            Log.d(TAG, "Supabase API Key configured: " + (SupabaseConfig.SUPABASE_ANON_KEY != null && !SupabaseConfig.SUPABASE_ANON_KEY.isEmpty()));

            // Initialize Supabase client
            SupabaseClient.initialize(this);

            Log.i(TAG, "✓ Supabase initialized successfully!");
            Log.i(TAG, "✓ Supabase is ready for data synchronization");

            // Test connection and perform initial sync
            testConnectionAndSync();

        } catch (Exception e) {
            Log.e(TAG, "✗ Failed to initialize Supabase: " + e.getMessage(), e);
        }
    }

    private void testConnectionAndSync() {
        new Thread(() -> {
            try {
                Log.d(TAG, "Testing Supabase connection...");
                boolean isConnected = SupabaseClient.getInstance().testConnection();

                if (isConnected) {
                    Log.i(TAG, "✓ Supabase connection test SUCCESSFUL");
                    Log.i(TAG, "✓ Data sync is enabled and operational");

                    // Check if initial sync has been done
                    SharedPreferences prefs = getSharedPreferences(PREFS_NAME, MODE_PRIVATE);
                    boolean syncDone = prefs.getBoolean(KEY_INITIAL_SYNC_DONE, false);

                    if (!syncDone) {
                        Log.i(TAG, " First launch detected - starting initial data migration...");
                        performInitialDataSync(prefs);
                    } else {
                        Log.d(TAG, "✓ Initial sync already completed on previous launch");
                    }
                } else {
                    Log.w(TAG, "✗ Supabase connection test FAILED");
                    Log.w(TAG, "✗ Data sync may not work properly");
                }
            } catch (Exception e) {
                Log.e(TAG, "✗ Supabase connection test error: " + e.getMessage(), e);
            }
        }).start();
    }

    private void performInitialDataSync(SharedPreferences prefs) {
        try {
            // Get sync manager and trigger full sync
            SupabaseSyncManager syncManager = SupabaseSyncManager.getInstance(this);

            Log.i(TAG, "════════════════════════════════════════");
            Log.i(TAG, " INITIAL DATA MIGRATION STARTED");
            Log.i(TAG, "This will sync all existing local data to Supabase");
            Log.i(TAG, "════════════════════════════════════════");

            // Perform the sync (runs in background)
            syncManager.syncAllLocalData();

            // Mark sync as done (we mark it now, but actual sync happens async)
            // If sync fails, user can reset by clearing app data
            prefs.edit().putBoolean(KEY_INITIAL_SYNC_DONE, true).apply();

            Log.i(TAG, "✓ Initial sync triggered successfully");
            Log.i(TAG, " Check logs for detailed sync progress");

        } catch (Exception e) {
            Log.e(TAG, "❌ Failed to trigger initial sync: " + e.getMessage(), e);
        }
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import java.util.ArrayList;
import java.util.List;

public class ViewEditResultsActivity extends AppCompatActivity implements ResultsAdapter.OnResultActionListener {

    private RecyclerView rvResults;
    private ResultsAdapter adapter;
    private DatabaseHelper dbHelper;
    private List<Result> resultsList = new ArrayList<>();

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_view_edit_results);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        getSupportActionBar().setTitle("View & Edit Results");

        dbHelper = new DatabaseHelper(this);
        rvResults = findViewById(R.id.rvResults);
        rvResults.setLayoutManager(new LinearLayoutManager(this));

        loadResults();
    }

    private void loadResults() {
        resultsList.clear();

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);
        int teacherId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);

        if (teacherGrade == -1 || teacherId == -1) {
            Toast.makeText(this, "Unable to load results for your grade", Toast.LENGTH_SHORT).show();
            return;
        }

        SQLiteDatabase db = dbHelper.getReadableDatabase();

        // Query to get all results for students in the teacher's grade
        String query = "SELECT r." + DatabaseHelper.RESULT_ID + ", " +
                "r." + DatabaseHelper.RESULT_SUBJECT + ", " +
                "r." + DatabaseHelper.RESULT_TERM + ", " +
                "r." + DatabaseHelper.RESULT_MARKS + ", " +
                "r." + DatabaseHelper.RESULT_COMMENT + ", " +
                "s." + DatabaseHelper.STUDENT_NAME + ", " +
                "s." + DatabaseHelper.STUDENT_ID +
                " FROM " + DatabaseHelper.TABLE_RESULTS + " r " +
                "INNER JOIN " + DatabaseHelper.TABLE_STUDENT + " s ON r." +
                DatabaseHelper.RESULT_FK_STUDENT_ID + " = s." + DatabaseHelper.STUDENT_ID +
                " WHERE s." + DatabaseHelper.STUDENT_GRADE + " = ? " +
                " ORDER BY s." + DatabaseHelper.STUDENT_NAME + " ASC, r." +
                DatabaseHelper.RESULT_SUBJECT + " ASC, r." + DatabaseHelper.RESULT_TERM + " ASC";

        Cursor cursor = db.rawQuery(query, new String[]{String.valueOf(teacherGrade)});

        if (cursor != null && cursor.moveToFirst()) {
            do {
                int resultId = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_ID));
                String subject = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_SUBJECT));
                String term = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_TERM));
                int marks = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_MARKS));
                String comment = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_COMMENT));
                String studentName = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_NAME));
                int studentId = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_ID));

                Result result = new Result(resultId, studentId, studentName, subject, term, marks, comment);
                resultsList.add(result);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        adapter = new ResultsAdapter(resultsList, this);
        rvResults.setAdapter(adapter);

        if (resultsList.isEmpty()) {
            Toast.makeText(this, "No results found for your grade", Toast.LENGTH_SHORT).show();
        }
    }

    @Override
    public void onEditResult(Result result, int position) {
        // Open edit dialog
        EditResultDialog dialog = new EditResultDialog(this, result, updatedResult -> {
            // Update in database with individual parameters
            if (dbHelper.updateResult(
                    updatedResult.getResultId(),
                    updatedResult.getSubject(),
                    updatedResult.getTerm(),
                    updatedResult.getMarks(),
                    updatedResult.getComment())) {
                // Update in list
                resultsList.set(position, updatedResult);
                adapter.notifyItemChanged(position);
                Toast.makeText(this, "Result updated successfully", Toast.LENGTH_SHORT).show();
            } else {
                Toast.makeText(this, "Failed to update result", Toast.LENGTH_SHORT).show();
            }
        });
        dialog.show();
    }

    @Override
    public void onDeleteResult(Result result, int position) {
        // Show confirmation dialog
        new androidx.appcompat.app.AlertDialog.Builder(this)
                .setTitle("Delete Result")
                .setMessage("Are you sure you want to delete this result for " + result.getStudentName() + "?")
                .setPositiveButton("Delete", (dialog, which) -> {
                    if (dbHelper.deleteResult(result.getResultId())) {
                        resultsList.remove(position);
                        adapter.notifyItemRemoved(position);
                        Toast.makeText(this, "Result deleted successfully", Toast.LENGTH_SHORT).show();
                    } else {
                        Toast.makeText(this, "Failed to delete result", Toast.LENGTH_SHORT).show();
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    @Override
    public boolean onSupportNavigateUp() {
        onBackPressed();
        return true;
    }
}

package com.example.studentintelligentsystem.supabase;

import android.util.Log;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/**
 * Supabase Authentication Manager
 * Handles login by querying Supabase database for user credentials
 */
public class SupabaseAuthManager {
    private static final String TAG = "SupabaseAuthManager";

    public SupabaseAuthManager() {
        // Empty constructor
    }

    /**
     * Login user by querying Supabase
     * @param email User's email
     * @param password User's plaintext password (will be hashed)
     * @param role User role: Admin, Teacher, or Parent
     * @return JSONObject with user data if login successful, null otherwise
     */
    public JSONObject login(String email, String password, String role) {
        if (!SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Supabase not configured");
            return null;
        }

        try {
            // Hash password to match stored hash
            String hashedPassword = hashPassword(password);

            // Determine table name based on role
            String tableName = getTableNameForRole(role);
            if (tableName == null) {
                Log.e(TAG, "Invalid role: " + role);
                return null;
            }

            Log.d(TAG, "Attempting login for " + role + " with email: " + email);

            // Query Supabase for user
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName
                + "?email=eq." + email
                + "&password_hash=eq." + hashedPassword
                + "&select=*";

            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();

                // Parse response
                JSONArray users = new JSONArray(response.toString());

                if (users.length() > 0) {
                    JSONObject user = users.getJSONObject(0);
                    Log.i(TAG, "✓ Login successful for " + role + ": " + email);
                    return user;
                } else {
                    Log.w(TAG, "✗ Login failed: Invalid credentials for " + role);
                    return null;
                }

            } else {
                Log.e(TAG, "✗ Login failed: HTTP " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error during login: " + e.getMessage(), e);
            return null;
        }
    }

    /**
     * Get table name based on user role
     */
    private String getTableNameForRole(String role) {
        switch (role) {
            case "Admin":
                return "admins";
            case "Teacher":
                return "teachers";
            case "Parent":
                return "parents";
            default:
                return null;
        }
    }

    /**
     * Hash password using SHA-256
     * Must match the hashing in DatabaseHelper
     */
    private String hashPassword(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(password.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (Exception e) {
            Log.e(TAG, "Error hashing password", e);
            return null;
        }
    }
}

package com.example.studentintelligentsystem.supabase;

import android.content.Context;
import android.util.Log;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Supabase Client Singleton
 * Handles all communication with Supabase backend
 */
public class SupabaseClient {
    private static final String TAG = "SupabaseClient";
    private static SupabaseClient instance;
    private Context context;
    private boolean isInitialized = false;

    private SupabaseClient(Context context) {
        this.context = context.getApplicationContext();
    }

    /**
     * Initialize the Supabase client
     */
    public static synchronized void initialize(Context context) {
        if (instance == null) {
            instance = new SupabaseClient(context);
            instance.isInitialized = true;
            Log.d(TAG, "SupabaseClient initialized");
        }
    }

    /**
     * Get the singleton instance
     */
    public static synchronized SupabaseClient getInstance() {
        if (instance == null) {
            throw new IllegalStateException("SupabaseClient not initialized. Call initialize() first.");
        }
        return instance;
    }

    /**
     * Test connection to Supabase
     */
    public boolean testConnection() {
        if (!SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot test connection: Supabase not configured");
            return false;
        }

        try {
            // Try to query the profiles table (should exist)
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/profiles?limit=1";
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            int responseCode = conn.getResponseCode();
            conn.disconnect();

            Log.d(TAG, "Connection test response code: " + responseCode);
            return responseCode == 200 || responseCode == 201;

        } catch (Exception e) {
            Log.e(TAG, "Connection test failed: " + e.getMessage());
            return false;
        }
    }

    /**
     * Insert data into Supabase table
     */
    public boolean insertData(String tableName, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot insert: Supabase not properly initialized");
            return false;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "return=representation");
            conn.setDoOutput(true);

            // Write JSON data
            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 201) {
                Log.d(TAG, "Data inserted successfully to " + tableName);
                return true;
            } else {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getErrorStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                Log.e(TAG, "Insert failed: " + responseCode + " - " + response.toString());
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error inserting data to " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Update data in Supabase table
     */
    public boolean updateData(String tableName, String idColumn, String idValue, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot update: Supabase not properly initialized");
            return false;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName + "?" + idColumn + "=eq." + idValue;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("PATCH");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "return=representation");
            conn.setDoOutput(true);

            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 204) {
                Log.d(TAG, "Data updated successfully in " + tableName);
                return true;
            } else {
                Log.e(TAG, "Update failed: " + responseCode);
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error updating data in " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Query data from Supabase table
     */
    public String queryData(String tableName, String filter) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot query: Supabase not properly initialized");
            return null;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            if (filter != null && !filter.isEmpty()) {
                urlString += "?" + filter;
            }

            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                return response.toString();
            } else {
                Log.e(TAG, "Query failed: " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error querying data from " + tableName + ": " + e.getMessage(), e);
            return null;
        }
    }

    public boolean isInitialized() {
        return isInitialized;
    }
}

